export default [{"id":478,"question":"عفا الله عنك يا شيخ، أليس الصحيح ألا يتوضأ ولا يغتسل من غَسَّل ميتًا إذا لم يباشر تغسيله بيده؟","title":"هل يجب الغسل على من غَسَّل ميتًا؟","answer":"الجواب: كيف غَسَّله؟ س: بالقفازين من وراء حائل.  الشيخ: المعروف أن الوضوء من غُسل الميت مستحب، ثبت من حديث عائشة أنه كان يغتسل من غَسْل الميت عليه الصلاة والسلام، وثبت عن زوجة الصدِّيق أن الصحابة  أفتوها بعدم الغُسل لما اشتدّ عليها البرد، دل على أنه معروف عندهم الغسل لولا العذر.\n(دروس شرح بلوغ المرام، كتاب الطهارة)","link":"https://binbaz.org.sa/fatwas/6236/هل-يجب-الغسل-على-من-غسل-ميتا","audio":"https://files.zadapps.info/binbaz.org.sa/3'osl38.mp3","categories":["الغسل","غسل الميت وتجهيزه"]},{"id":480,"question":"الحكمة في الاغتسال لمن غَسَّل ميتًا؟","title":"ما الحكمة في الاغتسال لمن غَسَّل ميتًا؟","answer":"الجواب: لأنه في غسل الميت يوهن القوة، يتفكر الموت وما بعد الموت وتوهن قواه وتضعف قواه، ويصيبه شيء من الضعف؛ فالغسل يجبره وينشّطه ويقوِّيه.\n(دروس شرح بلوغ المرام، كتاب الطهارة)","link":"https://binbaz.org.sa/fatwas/6239/ما-الحكمة-في-الاغتسال-لمن-غسل-ميتا","audio":"https://files.zadapps.info/binbaz.org.sa/3'asl041.mp3","categories":["الغسل","غسل الميت وتجهيزه"]},{"id":764,"question":"سائلٌ يسأل عن حكم حلق الميت في المواضع التالية: العانة، والإبط، والوجه، وتقليم الأظافر، وذلك قبل التَّغسيل.ثم يسأل عن كيفية تغسيل الميت، وعن وضع يده اليمنى تحت رأسه بعد إنزاله في القبر، وعن اغتسال المُغسل بعد تغسيل الميت؟","title":"ما كيفية تغسيل الميت؟","answer":"الجواب: السُّنة في تغسيل الميت أنه أولًا: يُنَجَّى إن خرج منه شيءٌ، يُرفع قليلًا حتى يكون كهيئة الجالس بغير اعتدالٍ، ويُمسح بطنه مسحًا خفيفًا إن كان هناك شيءٌ وتهيَّأ للخروج يخرج، فإن خرج شيءٌ نجاه بخرقةٍ، وغسل فرجه ودبره إن خرج شيءٌ، ثم يُوضِّئه وضوء الصلاة؛ لأنَّ الرسول قال: ابدأن بميامنها ومواضع الوضوء منها، ثم بعد ذلك يُريق عليه الماء على جنبه الأيمن، ثم الأيسر، ويكون في الماء شيءٌ من السّدر، يغسل برغوته رأسه وبدنه، ويجعل فيه كافورًا أو شيئًا من كافورٍ؛ لأنه يطيب الرائحة، ويصلب الجسم.\nفيغسله بماء وسدر، ويبدأ بميامنه ومواضع الوضوء منه، ثم يُريق عليه الماء ثلاث مراتٍ، هذا هو الأفضل، فإن احتاج إلى زيادةٍ فخمس مرات، وإذا احتاج إلى زيادةٍ لكثرة الأوساخ فإلى سبعٍ، كل هذا جاء في حديث أم عطية، ويُستحب أن يكون فيه كافور؛ لما فيه من الرائحة الطيبة، والتصليب، والتقوية للأعضاء.\nثم بعد ذلك يجعله في لفائف ثلاث إن كان رجلًا، تُبْسَط واحدة فوق واحدة، ثم تُلفّ عليه الأولى، ثم الثانية، وهكذا، ويعقد ما عند رأسه وما عند رجليه والوسط ثلاث عقد، حزام يربطه، وإذا وُضِعَ في القبر تُحلّ هذه الأحزمة، وتُترك في مكانها، لكن تحلّ، ويُوضع على جنبه الأيمن، ولا تُجعل يده تحت رأسه، بل تُسدل يداه على جنبيه، ولا يُكشف رأسه ولا وجهه، لا هو، ولا المرأة، يُغطَّى، على جنبه الأيمن إلى القبلة.\nومَن غسَّله شُرِعَ له الغسل، ولا يجب عليه، مَن غسَّله يُشرع له الغسل، كان النبيُّ ﷺ يغتسل من غسل الميت، فالغسل من غسل الميت أمرٌ مطلوبٌ شرعًا، وليس بواجبٍ.\nأما العانة فلا، يتركها، لا يحلق عانته، ولا ينتف إبطه، لا يتعرض له، لكن إذا كان الشاربُ فيه طول أو في أظفاره طول قصَّها؛ لأنَّ أخذها ميسَّرٌ، إن كان في شاربه طولٌ أو في أظفاره طولٌ قصَّها، وإن كانت خفيفةً لا يحتاج إلى ذلك، أما العورة فلا دليلَ على حلقها، ما هو بمقام حلقها، والله المستعان.\nس: والمُغسل له أن يكشف عن العورة؟\nالشيخ: لا، يستر العورة، ما بين السرة والركبة يستره، وإذا دعت الحاجةُ إلى غسل العورة غسلها بخرقةٍ دون يده.\n س: ولا ينظر فيها هو؟\nالشيخ: ولا ينظرها، ولا يكشفها.","link":"https://binbaz.org.sa/fatwas/20711/ما-كيفية-تغسيل-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0594ما كيفية تغسيل الميت؟ ابن باز رحمه الله فتاوى المحاضرات.mp3","categories":["غسل الميت وتجهيزه"]},{"id":2173,"question":"بعض الحُجَّاج بعد الانتهاء من الحج يقوم بغسل ملابس الإحرام بزمزم، ويجعلها كفنًا له، فهل في هذا شيء؟","title":"حكم غسل ملابس الإحرام بزمزم وجعلها كفنًا","answer":"الجواب:\nلا حرج؛ لأنَّ ماء زمزم ماءٌ مباركٌ.","link":"https://binbaz.org.sa/fatwas/22294/حكم-غسل-ملابس-الاحرام-بزمزم-وجعلها-كفنا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/غسل ملابس الإحرام بماء زمزم وجعلها كفنا.mp3","categories":["غسل الميت وتجهيزه"]},{"id":2779,"question":"بالنسبة للذي يقام عليه حد يُغَسّل؟","title":"هل يُغَسّل من أقيم عليه الحد؟","answer":"الجواب: يُغَسّل ويُصلى عليه نعم، مثلما غَسِّل ماعزًا والغامدية، رُجِموا وغُسّلوا وصُلي عليهم.","link":"https://binbaz.org.sa/fatwas/22927/هل-يغسل-من-اقيم-عليه-الحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يُغَسل من إيم عليه الحد.mp3","categories":["غسل الميت وتجهيزه"]},{"id":2783,"question":"المحروق بالنار هل يُغَسَّل؟","title":"هل يُغَسَّل المحروقُ بالنار؟","answer":"الجواب: إنْ أمكن، وإلا يُمِّمْ، إن أمكن يُغَسَّل غُسِّل، وإن كان يُخشى تَقَطُّعُه يُمِّم ويُصلى عليه، إذا احترق بالنار يُمِّم وجهه وكَفَّاه بالتراب، أما إذا تيسر غسله إذا كان متماسكًا يُغَسَّل.","link":"https://binbaz.org.sa/fatwas/22931/هل-يغسل-المحروق-بالنار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يغسل المحروق بالنار.mp3","categories":["غسل الميت وتجهيزه"]},{"id":3365,"question":"المرأة الحائض تُغَسّل الميت؟","title":"هل يجوز للمرأة الحائض تغسيل الميت؟","answer":"الجواب: إذا دعت الحاجة لا بأس، والأمر ما فيه شيء، كَمَيّت، تُغَسّل ميتًا، أو زوجها.","link":"https://binbaz.org.sa/fatwas/23532/هل-يجوز-للمراة-الحاىض-تغسيل-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تغسل المرأة الحائض الميت.mp3","categories":["غسل الميت وتجهيزه","الحيض والنفاس","قضايا المرأة"]},{"id":4036,"question":"أين يوضع الحنوط؟","title":"أين يوضع الحنوط من بدن الميت؟","answer":"الجواب: على بدن الميت، في مغابن الميت، في رأسه ولحيته وآباطه، ويطيب ركبتيه، وجميع بدنه، كذلك الكفن يطيب.","link":"https://binbaz.org.sa/fatwas/24272/اين-يوضع-الحنوط-من-بدن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أين يوضع الحنوط.mp3","categories":["غسل الميت وتجهيزه"]},{"id":4670,"question":"ولو كُفِّن الميتُ المُحرم في الثياب المُعتادة؟","title":"حكم تكفين الميت المحرم في الثياب المُعتادة","answer":"الجواب: غطوا رأسه يعني؟\nس: نعم، غطّوا رأسه بالكفن المُعتاد، ليس بالإحرام؟\nج: ما هو ببعيدٍ، لو كان قريبًا في الحال يُنبش ويُؤخَّر عن رأسه لا بأس، أما إذا تأخَّر ما يحتاج، لكن ما دام في الحال ما بعد تغير، في الحال لا مانع، إن قيل بجوازه لا بأس؛ لإزالته عن رأسه.","link":"https://binbaz.org.sa/fatwas/24962/حكم-تكفين-الميت-المحرم-في-الثياب-المعتادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تكفين الميت المحرم في الثياب المُعتادة.mp3","categories":["غسل الميت وتجهيزه"]},{"id":5575,"question":"الشهيد يُكفَّن؟","title":"هل يُغسل الشهيد ويُكفّن؟","answer":"الجواب: يُدفن في ثيابه، لا يُغسّل، ولا يُكفن، يُدفن في ثيابه، شهيد المعركة في سبيل الله، كما فعل الرسول في شُهداء أُحد، أمرهم أن يُدفنوا في ثيابهم، ولم يُغسلوا، ولم يُصلَّ عليهم، شهداء: بَلْ أَحْيَاءٌ عِنْدَ رَبِّهِمْ يُرْزَقُونَ [آل عمران:169]. س: الشهيد إذا أُصيب بأرض المعركة ولكن لم يمت إلا خارج أرض المعركة؟ ج: يُغسّل، إذا نُقل حيًّا ثم مات بعد ذلك يُغسّل. س: هل يشترط أن يكون مقتولًا ظلمًا في التغسيل؟ ج: يُغسّل ولو أنه مقتول ظلمًا، والمقتول حدًّا يُغسل على كل حالٍ، ما في شك، إذا قُتل حدًّا يُغسّل: كالمرجوم، الزاني المحصن يُرجم ويُغسل. س: الدليل لمَن استثنى المظلوم، وجه الدلالة؟ ج: يُلحق بالشهداء، يعني أنه شهيد، وكون تسميته شهيدًا ما يلزم منه، حتى مَن مات بالبطن يُسمَّى: شهيدًا، ما يُغسل؟! المطعون والمبطون شُهداء ويُغسَّلون، تسميته: شهيدًا لا تمنع من تغسيله، فإن الشهادة أمرها عام واسع، لكن شهيد المعركة خاصَّةً هو الذي لا يُغسّل للنصِّ فيه، وأما الشهداء الآخرون فيُغسّلون: المقتول ظلمًا، والمقتول بالبطن، أنواع الشهادة: المبطون شهيد، وصاحب الهدم والغرق يُغسَّلون.[1]","link":"https://binbaz.org.sa/fatwas/31527/هل-يغسل-الشهيد-ويكفن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 015.mp3","categories":["غسل الميت وتجهيزه"]},{"id":5576,"question":"الذي أصابه الحريق، مات بالحريق؟","title":"هل يُغسل من مات حريقًا؟","answer":"الجواب: يُغسّل إذا تيسر، وإلا يُيَمَّم، إذا تمكَّنوا من تغسيل الحريق وإلا يُيَمَّم؛ لأنه قد يُذهب الماءُ أجزاءً منه بغسله؛ لكونه احترق، لكن إذا تيسر أن يُغسَّل والحرق ما يمنع غسله لا بأس، وإلا يُيَمَّم، إذا كان الحريقُ قطعه وأحرقه يُيَمَّم.[1]","link":"https://binbaz.org.sa/fatwas/31528/هل-يغسل-من-مات-حريقا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 016.mp3","categories":["غسل الميت وتجهيزه"]},{"id":5704,"question":"هل يصلى على قاتل نفسه، والتارك للجمعة والجماعة، وآكل الربا؟ وهل يصلى على المقتول حدًا؟","title":"حكم الصلاة على مرتكب الكبائر","answer":"الجواب: القاعدة أن العاصي يصلى عليه، العاصي الذي ليس بكافر يصلى عليه، لكن إذا ترك الصلاة عليه بعض الكبار، مثل العالم والقاضي، والرئيس من باب الزجر لغيره، والتنفير من هذا العمل السيئ،؛ لأنه يرابي، أو لأنه قتل نفسه، فهذا من باب التنفير من هذه المعاصي، وإلا فيصلى عليه.  المقصود: أنه لا بدّ من عناية بهذا، فالذي لا يعرف المساجد يظن به السوء -نسأل الله السلامة- لكن لا يقطع بكفره، لا مانع من الصلاة عليه ما دام مع المسلمين، ويشهد أن لا إله إلا الله، وأن محمدًا رسول الله، ويعامل كمعاملة المسلمين، فالأفضل بقاؤه في الإسلام حتى تعلم أنه لا يصلي بالكلية.","link":"https://binbaz.org.sa/fatwas/1013/حكم-الصلاة-على-مرتكب-الكباىر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_38.mp3","categories":["غسل الميت وتجهيزه","الصلاة على الميت"]},{"id":5705,"question":"ثبت أن الرسول ﷺ صلى على جنازة في القبر بعد قبرها بمدة، فهل يجوز للإنسان أن يصلي على قريبه إذا جاء إلى قبره خلال عشرة أيام من موته، أو أقل، أو أكثر؟","title":"هل يصلى على الميت في القبر؟ وما مدة ذلك؟","answer":"الجواب:  السنة الصلاة على القبر، إذا كان ما صلى على الميت يستحب له أن يصلي على القبر، فقد ثبت عنه -عليه الصلاة والسلام- أنه ذكر له أن امرأة كانت تقم المسجد، كانت تكنس المسجد، كانت امرأة سوداء تكنس المسجد، فماتت ليلًا، فغسلها المسلمون، وصلوا عليها، ودفنوها في الليل، ولم يخبروا النبي ﷺ بذلك، وكرهوا أن يوقظوه، فلما أصبح، وأخبروه قال: أفلا كنتم آذنتموني؟! دلوني على قبرها فدلوه على قبرها، فصلى عليها -عليه الصلاة والسلام- وقال: لا يموتن أحد من المسلمين إلا أخبرتموني، فإن الله جاعل من صلاتي عليهم خيرًا لهم، وقال: نورًا لهم عليه الصلاة والسلام. هذه السنة؛ إذا كانت فاتته الصلاة على الميت يستحب للإنسان إذا تيسر له أن يذهب، ويصلي على القبر فهذا سنة، فعله النبي ﷺ مرات -عليه الصلاة والسلام- وفعله على أم سعد، وقد مضى لها شهر.  فذكر العلماء أنه إذا كان شهر، وما حوله، وأقل فلا بأس، وإذا طالت المدة فلا حاجة إلى ذلك؛ لأن الرسول لم يفعل ذلك بعد طول المدة -عليه الصلاة والسلام- إنما فعله في حدود شهر فأقل، أما إذا طالت المدة على الميت فلا يشرع الصلاة عليه لمن غاب عنه.  السؤال: بالنسبة للمسجد الذي كانت تقمه المرأة هل هو مسجد الرسول أو غيره؟ الجواب:  مسجد الرسول ﷺ. السؤال: هل هو رجل، أو امرأة؟ الجواب:  جاء في رواية أنه خادم، وجاء في رواية أنها خادمة، امرأة سوداء، ولا مانع أن يكون خادم وخادمة، وهذا يدل على فضل قم المساجد، وتنظيف المساجد، وأن قمها وتنظيفها من السنة.  وقد أمر النبي ﷺ بأن تبنى المساجد في الدور في القبائل، وأن تنظف، وأن تطيب، وقال -عليه الصلاة والسلام-: عرضت عليّ أجور أمتي حتى القذاة يخرجها الرجل من المسجد يعني عرضت عليه الأجور حتى القذاة، مثل قطعة عود، أو خرقة صغيرة يأخذها الرجل، ويزيلها من المسجد، هذا من الأجور والله أكبر.","link":"https://binbaz.org.sa/fatwas/1011/هل-يصلى-على-الميت-في-القبر-وما-مدة-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_36.mp3","categories":["غسل الميت وتجهيزه","الصلاة على الميت"]},{"id":5708,"question":"هل يصلى على قاتل نفسه، والتارك للجمعة والجماعة، وآكل الربا؟ وهل يصلى على المقتول حدًا؟","title":"حكم الصلاة على مرتكب الكبائر","answer":"الجواب: القاعدة أن العاصي يصلى عليه، العاصي الذي ليس بكافر يصلى عليه، لكن إذا ترك الصلاة عليه بعض الكبار، مثل العالم والقاضي، والرئيس من باب الزجر لغيره، والتنفير من هذا العمل السيئ،؛ لأنه يرابي، أو لأنه قتل نفسه، فهذا من باب التنفير من هذه المعاصي، وإلا فيصلى عليه.  المقصود: أنه لا بدّ من عناية بهذا، فالذي لا يعرف المساجد يظن به السوء -نسأل الله السلامة- لكن لا يقطع بكفره، لا مانع من الصلاة عليه ما دام مع المسلمين، ويشهد أن لا إله إلا الله، وأن محمدًا رسول الله، ويعامل كمعاملة المسلمين، فالأفضل بقاؤه في الإسلام حتى تعلم أنه لا يصلي بالكلية.","link":"https://binbaz.org.sa/fatwas/1013/حكم-الصلاة-على-مرتكب-الكباىر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_38.mp3","categories":["غسل الميت وتجهيزه","الصلاة على الميت"]},{"id":5711,"question":"ثبت أن الرسول ﷺ صلى على جنازة في القبر بعد قبرها بمدة، فهل يجوز للإنسان أن يصلي على قريبه إذا جاء إلى قبره خلال عشرة أيام من موته، أو أقل، أو أكثر؟","title":"هل يصلى على الميت في القبر؟ وما مدة ذلك؟","answer":"الجواب:  السنة الصلاة على القبر، إذا كان ما صلى على الميت يستحب له أن يصلي على القبر، فقد ثبت عنه -عليه الصلاة والسلام- أنه ذكر له أن امرأة كانت تقم المسجد، كانت تكنس المسجد، كانت امرأة سوداء تكنس المسجد، فماتت ليلًا، فغسلها المسلمون، وصلوا عليها، ودفنوها في الليل، ولم يخبروا النبي ﷺ بذلك، وكرهوا أن يوقظوه، فلما أصبح، وأخبروه قال: أفلا كنتم آذنتموني؟! دلوني على قبرها فدلوه على قبرها، فصلى عليها -عليه الصلاة والسلام- وقال: لا يموتن أحد من المسلمين إلا أخبرتموني، فإن الله جاعل من صلاتي عليهم خيرًا لهم، وقال: نورًا لهم عليه الصلاة والسلام. هذه السنة؛ إذا كانت فاتته الصلاة على الميت يستحب للإنسان إذا تيسر له أن يذهب، ويصلي على القبر فهذا سنة، فعله النبي ﷺ مرات -عليه الصلاة والسلام- وفعله على أم سعد، وقد مضى لها شهر.  فذكر العلماء أنه إذا كان شهر، وما حوله، وأقل فلا بأس، وإذا طالت المدة فلا حاجة إلى ذلك؛ لأن الرسول لم يفعل ذلك بعد طول المدة -عليه الصلاة والسلام- إنما فعله في حدود شهر فأقل، أما إذا طالت المدة على الميت فلا يشرع الصلاة عليه لمن غاب عنه.  السؤال: بالنسبة للمسجد الذي كانت تقمه المرأة هل هو مسجد الرسول أو غيره؟ الجواب:  مسجد الرسول ﷺ. السؤال: هل هو رجل، أو امرأة؟ الجواب:  جاء في رواية أنه خادم، وجاء في رواية أنها خادمة، امرأة سوداء، ولا مانع أن يكون خادم وخادمة، وهذا يدل على فضل قم المساجد، وتنظيف المساجد، وأن قمها وتنظيفها من السنة.  وقد أمر النبي ﷺ بأن تبنى المساجد في الدور في القبائل، وأن تنظف، وأن تطيب، وقال -عليه الصلاة والسلام-: عرضت عليّ أجور أمتي حتى القذاة يخرجها الرجل من المسجد يعني عرضت عليه الأجور حتى القذاة، مثل قطعة عود، أو خرقة صغيرة يأخذها الرجل، ويزيلها من المسجد، هذا من الأجور والله أكبر.","link":"https://binbaz.org.sa/fatwas/1011/هل-يصلى-على-الميت-في-القبر-وما-مدة-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_36.mp3","categories":["غسل الميت وتجهيزه","الصلاة على الميت"]},{"id":5718,"question":"قوله: ويقدم أسن فأسبق يعني عند الصلاة على الجنائز، فهل يجعل الأفضل من قبل القبلة، والمفضول من قبل الإمام يعني بالعكس؟","title":"كيفية وضع الجنائز عند الصلاة عليها","answer":"الجواب: المشهور أنه يقدم الرجال، ثم النساء عند الإمام في الصلاة على الجنائز، يقدم الرجال، ثم الصبيان، ثم النساء في الجنائز، هكذا جاءت النصوص، يقدم أولًا الرجال، ثم النساء يكن من جهة القبلة، ويكون الأفضل إلى الإمام الرجال، ثم الصبيان إلى الإمام، وخلفهم من جهة القبلة النساء، هذا هو المشروع، وهكذا في الصفوف، الصفوف الأول تكون للرجال، ثم الصبيان، ثم النساء خلفهم.  السؤال: ياشيخ، الله يبارك فيك، ما فهنما الكلام هذا، إذا كان فيه رجال ونساء كيف نضعهم؟ الجواب: الجنازة أولًا، الرجل يكون قرب الإمام قريبًا منه، ثم يليه في الصف الصبي، ثم المرأة من جهة القبلة.","link":"https://binbaz.org.sa/fatwas/1030/كيفية-وضع-الجناىز-عند-الصلاة-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_52.mp3","categories":["غسل الميت وتجهيزه","الصلاة على الميت"]},{"id":5804,"question":"ما مدى صحة الحديث الذي يقول: \"من غسل مسلمًا، وستر عيبه خرج من ذنوبه كيوم ولدته أمه\"؟ وهل يجب دعاء الاستفتاح عند الصلاة على الميت، أم لا؟","title":"الحكم على حديث: \"من غسل مسلماً وستر عيبه\"","answer":"الجواب: ما أعرف له أصلًا، هذا الحديث: \"من غسل مسلمًا، وستر عيبه خرج من ذنوبه كيوم ولدته أمه\" ما أعرف له أصلًا، ولكن يستحب الستر على الموتى، وعدم إفشاء ما قد يظهر من مساويهم.  الغاسل يستحب له أن يستر على الناس، ويظهر المحاسن، ويستر المساوئ، هذا هو الذي نص عليه أهل العلم، وجاء فيه بعض الأحاديث الضعيفة، فالسنة أن الغاسل يستر إذا رأى شيئًا يزعجه، ولا يبين؛ لأن هذا نوع من الغيبة، ولكن إذا رأى نورًا، أو رأى محاسن بين ذلك.","link":"https://binbaz.org.sa/fatwas/1130/الحكم-على-حديث-من-غسل-مسلما-وستر-عيبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_136.mp3","categories":["غسل الميت وتجهيزه","الحكم على الأحاديث"]},{"id":5815,"question":"هل قاتل نفسه يغسل، ويصلى عليه؟","title":"حكم الغسل والصلاة على قاتل نفسه","answer":"الجواب: قاتل نفسه يغسل، ويصلى عليه، ويدفن مع المسلمين؛ لأنه عاص ما هو كافر، قتل النفس معصية، ما كفر، فإذا قتل نفسه -والعياذ بالله- يغسل، ويصلى عليه، ويكفن، ويصلى عليه، ويدفن مع المسلمين، لكن ينبغي للإمام الأكبر، ولمن له أهمية أن يترك الصلاة عليه من باب الإنكار، لئلا يظن أنه راض عن عمله.  فالإمام الأكبر السلطان، أو القضاة، أو رئيس البلد، وقاضي البلد، أو أميرها إذا ترك ذلك من باب إنكار هذا الشيء، وإعلان أن هذا خطأ؛ فهذا حسن، ولكن يصلي عليه بعض المسلمين.","link":"https://binbaz.org.sa/fatwas/1145/حكم-الغسل-والصلاة-على-قاتل-نفسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_149.mp3","categories":["غسل الميت وتجهيزه","الصلاة على الميت"]},{"id":5818,"question":"هل يجوز أخذ شارب، وآباط الميت، وكذلك عانته؟","title":"حكم قص شعر شارب الميت وعانته وإبطه وأظافره","answer":"الجواب: هذا يستحب، قص شاربه، وقلم أظفاره إذا كان فيه شيء يستحب قلم أظفاره.  وأما حلق العانة فهو محل نظر، فلا نعلم دليلًا ظاهرًا، وإلا قد يشق ذلك في العورة، فهذا يحتاج إلى دليل، والأقرب عندي ترك ذلك.  أما قص الشارب، وقلم الظفر فهو ميسر، وقد نص عليه العلماء، فالأولى أخذ ذلك إن كان الظفر طويلًا والشارب يقصه، هذا أفضل.","link":"https://binbaz.org.sa/fatwas/1137/حكم-قص-شعر-شارب-الميت-وعانته-وابطه-واظافره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_143.mp3","categories":["غسل الميت وتجهيزه","قضايا المرأة"]},{"id":5824,"question":"آمل شرح كيفية تكفين الميت بالنسبة للرجل، والأنثى؟","title":"كيفية تكفين الميت رجلا وأنثى","answer":"الجواب: السنة أن يكفن الرجل في ثلاثة أثواب بيض، هذه السنة كما كفن بها النبي ﷺ، وإن كفن في ثوب واحد، ورأسه يعمه، ويستره كفى، وإن كفن في قميص، وإزار، ولفافة جاز، فليس في التكفين حد محدود. إذا كفن في لفافة واحدة، أو لفافتين، أو ثلاث، أو في قميص ولفافة، أو في قميص وإزار ولفافة كله جائز، والحمد لله كله واسع.  ولكن الأفضل مثل ما كفن النبي ﷺ مثل ما أجرى الله لنبيه ﷺ كفنه الصحابة في ثلاث لفائف بيض، أدرج فيها إدراجًا هذا هو الأفضل، وإن كفن في ثوبين، أو في واحد، أو في قميص وإزار؛ فلا بأس. كذلك المرأة تكفن في ثوب واحد يسترها، في لفافة واحدة تسترها، أو في مدرعة ولفافة، أو في مدرعة وإزار ولفافة كله جائز.  وإذا كفنت في خمسة: إزار وخمار وقميص ولفافتين فهذا هو الأفضل، كما ذكر أهل العلم، وجاء في بعض الأخبار الدالة على ذلك.  هذا هو أفضل ما يكون قميص وإزار وخمار ولفافتين للمرأة، وإن كفنت في ثوب واحد، يعني لفافة واحدة يسترها كلها، أو في لفافتين، أو في قميص ولفافة، أو في قميص وخمار ولفافة، فكله طيب، ما في حد محدود، والأمر في هذا واسع.","link":"https://binbaz.org.sa/fatwas/1163/كيفية-تكفين-الميت-رجلا-وانثى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_162.mp3","categories":["غسل الميت وتجهيزه","الحيض والنفاس","قضايا المرأة"]},{"id":5914,"question":"هل يجوز لي شرعًا أن أقوم بتجهيز لوازم الدفن بالنيابة لزوجتي من دفن، وكفن، وخلافه؟","title":"حكم من قام بتجهيز لوازم دفن زوجته","answer":"الجواب: مؤنة التجهيز من مالها، إذا كان لها مال فمن مالها، فإن لم يكن لها مالها؛ فعلى وارثها، أنت والورثة،... يقوم بما يلزم من التجهيز، والكفن، والتغسيل، وحفر القبر، ونحو ذلك، وإذا كان لها مالها فتجهيزها من مالها يقدم على الورثة.","link":"https://binbaz.org.sa/fatwas/1236/حكم-من-قام-بتجهيز-لوازم-دفن-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_233.mp3","categories":["غسل الميت وتجهيزه","الصلاة على الميت"]},{"id":6163,"question":"قال العلماء إن الغسل من غسل الميت سنة، وليس بواجب، فهل الوضوء يجب على من غسل الميت، أم سنة كالغسل؟","title":"حكم الغسل والوضوء على من غسل ميتًا","answer":"الجواب: الغسل سنة، إذا غسل ميتًا السنة أن يغتسل، والوضوء أوجبه قوم، وليس عليه أدلة واضحة، لكن إن توضأ فحسن؛ خروجًا من الخلاف، وإن توضأ مع الغسل؛ فهو أكمل. لكن لا يجب الغسل، وإنما يستحب، أما الوضوء فالقول فيه قول أكثر جاء عن بعض الصحابة عن جابر، قيل: توضأ، فإذا توضأ مع الغسل؛ فهو أحوط، وأولى، لكن هذا إذا كان ما مس العورة. أما إذا مسه ويده مست عورة الميت؛ وجب عليه الوضوء بكل حال؛ لأن مس العورة ينقض الوضوء، ولا يمس العورة، فيجعل بينه وبين العورة شيئًا، خرقًا يغسل بها، وينظف بها، لكن لو قُدر أن يده أخطأت، ومست العورة وجب عليه الوضوء، أما إذا كان ما أصاب العورة؛ فالأولى له أن يتوضأ؛ خروجًا من الخلاف، وذلك طهارة، وخير كثير، والغسل سنة أيضًا.","link":"https://binbaz.org.sa/fatwas/1624/حكم-الغسل-والوضوء-على-من-غسل-ميتا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_515.mp3","categories":["غسل الميت وتجهيزه","الصلاة على الميت"]},{"id":7465,"question":"السؤال الثاني يتعلق بتغسيل المرأة، يقول فيها السائل: توفيت امرأة في مكان ليس فيه مغسلة ولا زوج لها، بل يوجد فيه ابنها، فهل يقوم ابنها بتغسيلها أم لا يقوم؟","title":"حكم من ماتت ولم يوجد من يغسلها إلا ابنها","answer":"الجواب:  الأرجح أنه لا يقوم، بل تيمم، يعني: ييممها وليها، فابنها ييممها، ويضرب التراب بيديه ويمس بهما وجهها وكفيها بنية غسل الموت ويكفي؛ لأن المرأة لا يغسلها إلا أحد شخصين، إما امرأة، وإما الزوج أو السيد الذي تباح له، أما في هذه الحال؛ لم يحضرها سوى ابنها أو أخيها أو عمها أو أجنبي فإنها تيمم على الراجح، يعني: يضرب التراب بيديه ويمسح بهما وجهها وكفيها بنية تغسيلها عن الموت. \nالمقدم: يعني: التيمم هنا يشابه التيمم للصلاة؟\nالشيخ: نعم، مثل الصلاة، سواء سواء.\nالمقدم: لا يمسح مثلاً على بقية جسمها.\nالشيخ: أبدًا وجهها وكفيها بس مثل الصلاة، مثل الذي عليه جنابة ولا عنده ماء. نعم.","link":"https://binbaz.org.sa/fatwas/4184/حكم-من-ماتت-ولم-يوجد-من-يغسلها-الا-ابنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_002/00202.mp3","categories":["غسل الميت وتجهيزه"]},{"id":7944,"question":"له سؤال آخر يقول فيه: إذا مات الميت شرعوا في ختانه وتقليم أظفاره وحلق عانته، فهل هذا جائز أم لا؟","title":"حكم حلق عانة الميت وختانه وتقليم أظفاره","answer":"الجواب: أما تقليم أظفاره وقص شاربه فهذا حسن، وأما حلق العانة فلا وجه له ولا حاجة إليه. نعم.","link":"https://binbaz.org.sa/fatwas/5471/حكم-حلق-عانة-الميت-وختانه-وتقليم-اظفاره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_068/06802.mp3","categories":["غسل الميت وتجهيزه"]},{"id":8104,"question":"الرسالة التالية باعثها أحد الإخوة يقول: عيسى خميس محمد صالح من الطائف، أخونا يسأل عن غسل الميت وعن الصلاة عليه؟","title":"كيفية غسل الميت وحكمه","answer":"الجواب: غسل الميت فرض كفاية، وهكذا الصلاة عليه، فإذا قام بغسله من يكفي سقط عن الباقين وهكذا الصلاة فغسله فرض النبي ﷺ أمر بغسل الميت، فالواجب تغسيله ويتولى ذلك العارف بذلك الثقة الأمين فيغسله، يعني: أن يغسلوا جميع بدنه ويبدءوا بتنجيته بخرقة، أي: يرفعه قليلاً لعله يخرج منه ما كان متهيأ للخروج من بول أو غيره ثم ينجيه بماء وخرقة ثم بعد ذلك يوضيه الوضوء الشرعي فيمسح فمه بالماء وأنفه بالماء وأن يزيل ما أن هناك ما في الأنف ويغسل وجهه ثلاثاً أو ثنتين أو واحدة والأفضل ثلاث، ثم يغسل ذراعيه ثلاثاً ثلاثاً أو واحدة واحدة أو ثنتين ثنتين كالوضوء، ثم يمسح رأسه وأذنيه ثم يغسل رجليه، ثم بعد ذلك يفيض الماء على جميع بدنه يعني يبدأ بالشق الأيمن ثم الأيسر، وإذا تيسر غسله بالسدر كان أفضل، فإن لم يتيسر السدر فالصابون أو الإشنان لتنظيفه، ويعتني برأسه ... في رأسه من السدر بعض الشيء حتى يزيل ما فيه من أذى ثم يفيض الماء على جسده كله بادئاً بالشق الأيمن ثم الأيسر، والأفضل أن يكرره ثلاثاً فإن لم تكف الثلاث لوجود أوساخ كرره خمساً، فإن لم تكف كرره سبعاً لما جاء في حديث غسل بنت النبي ﷺ زينب رضي الله عنها، فالنبي ﷺ قال: اغسلنها ثلاثاً أو خمساً أو سبعاً بماء وسدر واجعلن في الآخرة كافوراً أو شيئاً من كافور، فإذا تيسر السدر، جعل في الماء شيئاً من السدر وإن لم يتيسر جعل ما ينوب منابه مما ينظف من صابون أو إشنان أو غيرهما مما يحصل به التنظيف، وأن يكرر الغسل ثلاثاً أو خمساً أو سبعاً ولو احتيج إلى أكثر فعل.\nهذا هو الغسل الشرعي للرجل والمرأة جميعاً والرجل يغسله الرجال والمرأة تغسلها النساء، ويجوز للزوج أن يغسل زوجته، وللزوجة أن تغسل زوجها، كل هذا ثابت، وقد غسل علي  زوجته فاطمة رضي الله عنها وغسلت أسماء بنت عميس زوجها أبا بكر الصديق رضي الله عنهما جميعاً، فلا حرج في ذلك، وهكذا السرية الأمة التي يتسراها الرجل المملوكة إذا مات سيدها تغسله وهو يغسلها أيضاً كالزوجة، وهكذا الصغير الذي دون السبع يغسله الرجال والنساء؛ لأنه لا عورة له، فإذا بلغ سبعاً غسله الرجال، إذا بلغت الجارية سبعاً غسلها النساء، هذا هو المشروع.\nأما الصلاة فيجب أن يصلى عليه، والصلاة فرض كفاية فلو صلى عليه واحد مكلف كفى، ولكن كلما كثر الجمع وتيسر العدد الكثير فهو أفضل، وقد صح عن رسول الله ﷺ أنه قال: ما من رجل يصلي عليه أمة من الناس يبلغون مائة إلا قبل الله شفاعتهم فيه، إلا شفعهم الله فيه، وفي حديث ابن عباس رضي الله عنهما قال عليه الصلاة والسلام: ما من رجل مسلم يقوم على جنازته أربعون رجلاً لا يشركون بالله شيئاً إلا شفعهم الله فيه، فهذا يدل على أن وجود جماعة كثيرة في الصلاة أفضل حسب الإمكان حسب التيسير وإلا فالواجب شخص واحد مكلف إذا صلى عليه كفى، ولكن إذا تيسر عدد كبير فهو أفضل، والأفضل لأهل الميت أن يتحروا به المساجد التي فيها العدد الكثير حتى يكون هذا أنفع له، والله ولي التوفيق. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/5900/كيفية-غسل-الميت-وحكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_101/10107.mp3","categories":["غسل الميت وتجهيزه"]},{"id":9788,"question":"وأولى رسائل هذه الحلقة وردت من السائلة لطيفة عبد الله الزهراني من الطائف، تقول في رسالتها: إن بعض النساء يستعملن أدوات التجميل ومنها المنوكير التي توضع بأصابع اليد، فما الحكم إذا ماتت المرأة وهي في يدها؟ وما الواجب على أقربائها أن يفعلوه؟ أفيدونا أفادكم الله.","title":"حكم وضع الأصباغ على يد المرأة وإزالتها عند تغسيلها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفهذه المناكير يجب أن تزال وقت الوضوء ووقت الغسل، وهكذا لو ماتت وهي في أصابعها تزال عند غسلها؛ لأنها تمنع فيما بلغنا عنها تمنع وصول الماء إلى الأظفار؛ لأن لها جسم لها ثخانة تزال وتحك ولا مانع من ذلك، وإن تركتها بالكلية فهو أفضل، فإن الحناء يكفي، الحناء في تغيير الأصابع يكفي، ولا حاجة إلى المناكير التي استعملها الناس أخيراً، تركها أولى وأفضل؛ لأن المرأة قد تنساها وقت الوضوء قد لا تحكها فيكون في هذا ضرر عليها من جهة وضوئها.\nفالواجب أنها تزال عند الوضوء، حتى يصل الماء إلى الأظفار نفسها. نعم.\nالمقدم: وبالنسبة لحالة الوفاة؟\nالشيخ: كذلك وقت الغسل تزال، وقت غسل الميت. نعم.\nالمقدم: لا بد من إزالته؟\nالشيخ: نعم.\nالمقدم: ولو تركت يعني: هل يأثمون بذلك؟\nالشيخ: الأمر فيه سعة إن شاء الله، لكن إزالته أولى وأحوط.\nالمقدم: بارك الله فيكم وأثابكم الله.","link":"https://binbaz.org.sa/fatwas/7948/حكم-وضع-الاصباغ-على-يد-المراة-وازالتها-عند-تغسيلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_259/25901.mp3","categories":["غسل الميت وتجهيزه"]},{"id":9801,"question":"استفساره الأخير في رسالته يقول: هل يصح لرجل أن يغسل امرأته إذا ماتت أو بنت سنة أو سنتين ولو أجنبية عنه؟","title":"حكم غسل الزوج زوجته عند موتها","answer":"الجواب: لا بأس أن يغسل الرجل زوجته والمرأة زوجها جاءت به السنة عن النبي ﷺ فلا حرج في أن يغسل الرجل امرأته ولا حرج في أن تغسل المرأة زوجها، أما غيرها -غير الزوجة- فلا لكن السرية من جنس الزوجة الأمة السرية التي تسراها الرجل وجعلها محل وطء له؛ لأنه ملكها بالشراء أو بالهبة إذا وجد مماليك بالتوارث أو بالسبي الشرعي فلا بأس أن يتخذها الرجل سرية له ولا بأس أن تغسله ويغسلها كالزوجة، أما أمه وبنته وأخته ونحو هذا فلا يغسلهن بل يغسلهن النساء لكن البنت الصغيرة يغسلها الرجال لا بأس إذا كانت دون السبع كبنت الخمس والثلاث والأربع لا بأس، وهكذا الطفل الذي عمره سبع يغسله النساء أيضًا، ما دون السبع يغسله الرجال والنساء.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/7968/حكم-غسل-الزوج-زوجته-عند-موتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_196/19617.mp3","categories":["غسل الميت وتجهيزه"]},{"id":11238,"question":"من السودان هذا السائل الذي رمز لاسمه بـ (د. أ. ع) يقول: سؤالي الأول: من جهز ميتًا وهو عليه جنابة فما الحكم في ذلك؟ جزاكم الله خيرًا.","title":"حكم من جهز جنازة وهو على جنابة","answer":"الجواب:  لا حرج، لا حرج في ذلك، الحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/9410/حكم-من-جهز-جنازة-وهو-على-جنابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_291/29119.mp3","categories":["غسل الميت وتجهيزه"]},{"id":11366,"question":"من منطقة القنفذة السائلة (ش. أ. ي) تقول في السؤال الأول: عندما توفيت والدتي لم نضفر شعرها ثلاثة قرون كما هو معروف؛ وذلك لارتباكنا في ذلك الوقت، وإنما ترك كما هو بتمشيط يديها قبل الوفاة ضفيرتين، ولم يوضع طيب كافي فهل علينا حرج في ذلك يا سماحة الشيخ؟ أرجو الإفادة.","title":"جعل شعر المتوفاة ثلاث ضفائر مستحب وليس بلازم","answer":"الجواب:  ليس عليكم حرج في ذلك والحمد لله؛ لأن ضفر الثلاثة مستحب وليس بلازم، فترككم إياه ضفيرتين لا حرج في ذلك والحمد لله. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9548/جعل-شعر-المتوفاة-ثلاث-ضفاىر-مستحب-وليس-بلازم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_293/29309.mp3","categories":["غسل الميت وتجهيزه"]},{"id":11671,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع عودة مرعي الحويطي، أخونا يسأل ويقول: بعض الناس يترك وصية لورثته حين مرضه، أو عند حضور وفاته، ومن جملة هذه الوصايا يوصيهم بغسله أي: يغسلوه عدد زوجاته، فمثلًا: له زوجة واحدة يغسلوه غسلة واحدة، وإن كان له ثلاث زوجات يغسلوه ثلاث غسلات، وهكذا حسب عدد زوجاته، نرجو النصيحة لهؤلاء جزاكم الله خيرُا.","title":"أوصى أن يغسل بعدد زوجاته فما حكم تنفيذ الوصية؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه وأتباعه بإحسان، أما بعد: فهذه الوصية وصية لا أصل لها، باطلة، كونه يوصي بأن يغسل بعدد أزواجه هذا كلام باطل، ومن الخرافات، السنة أن يغسل الميت ثلاث غسلات، وإن دعت الحاجة إلى خمس، أو سبع وتر؛ كله طيب، والواجب مرة واحدة، الواجب أن يغسل غسلة واحدة، يعمم حتى يعم الماء بدنه، هذا الواجب، وإذا كرر ثلاث مرات؛ فهو أفضل، كما قال النبي ﷺ لما غسلت ابنته زينب: اغسلنها بثلاث، أو خمس، أو أكثر من ذلك إن رأيتن ذلك، واجعلن في الآخرة كافورًا .... فالسنة أن يغسل الميت ثلاثًا، هذا هو الأفضل، وإن دعت الحاجة إلى أكثر؛ فلا بأس وترًا، والواجب مرة واحدة، أما ما يتعلق بالزوجات؛ فهذا شيء لا أصل له. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9851/اوصى-ان-يغسل-بعدد-زوجاته-فما-حكم-تنفيذ-الوصية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_390/39001.mp3","categories":["غسل الميت وتجهيزه"]},{"id":11989,"question":"أحد الإخوة المستمعين آثر في رسالته عدم ذكر اسمه، يقول: استمعت إلى خطبة جمعة عن كيفية غسل وتكفين الميت، وعرفت في تلك الخطبة كما قال الخطيب: أن الميت يعرف من يغسله ومن يكفنه، وحينئذ بدأ يتردد في ذهني سؤال: كيف يكون ذلك؟ وجهوني جزاكم الله خيرًا.","title":"ما صحة أن الميت يعرف من يغسله، وكيفية غسل الميت؟","answer":"الجواب:  هذا لا أصل له، وليس هناك دليل يدل على أن الميت يعرف من غسله ومن كفنه، وهذا قول على الله بغير علم، السنة أن يغسل ثلاثًا أو خمسًا أو سبعًا، حسب حاجة الميت، والأفضل ألا تنقص عن ثلاث غسلات، وإن غسله مرة؛ كفى، لكن الأفضل يكرر ثلاثًا أو خمسًا؛ حتى يكون أنظف، وإن دعت الحاجة إلى سبع؛ فلا بأس، ثم يكفنه، والأفضل في ثلاثة أثواب بيض هذا هو الأفضل، يلف عليه الأولى، ثم الثانية، ثم الثالثة، وإن كفنه في ثوب واحد عمه كله؛ فلا بأس، أجزأ. ويطيب الميت بأنواع الطيب في رأسه، وفي لحيته، وفي مغابنه كل هذا جيد، كما أرشد إليه النبي -عليه الصلاة والسلام- إلا إذا كان محرمًا، مات وهو محرم؛ فلا يطيب، ولا يغطى رأسه........ يكفن في إزاره وردائه، ويكون رأسه ووجهه مكشوف إذا كان محرمًا. أما المرأة ولو كانت محرمة تكفن في الكفن، يعني: يعمها ويسترها كلها، بخلاف الرجل؛ لأنها عورة، فتكفن ولو كانت محرمة كفنًا يسترها كلها، حتى وجهها، لأن الممنوع في وجهها النقاب، ولكن تستر بغير النقاب بالكفن، والحمد لله، نعم. المقدم: الحمد لله، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10174/ما-صحة-ان-الميت-يعرف-من-يغسله-وكيفية-غسل-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_431/43103.mp3","categories":["غسل الميت وتجهيزه"]},{"id":12061,"question":"هل للمرأة أن تغسل زوجها عند وفاته؟","title":"حكم غسل المرأة لزوجها عند وفاته","answer":"الجواب:  نعم للمرأة أن تغسل زوجها؛ لأن الرسول ﷺ قال لـعائشة: لو مت قبلي؛ لغسلتك وعلي  غسل فاطمة، وأسماء بنت عميس غسلت الصديق أبا بكر زوجها، فلا حرج في ذلك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10246/حكم-غسل-المراة-لزوجها-عند-وفاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_434/43410.mp3","categories":["غسل الميت وتجهيزه"]},{"id":13436,"question":"يقول السائل: هل يحق للرجل أن يغسل من مات من محارمه، وذلك مثل والدته، أو ابنته، أو عمته وخالته، أم يقتصر على غسل الزوجة فقط، أفتونا مأجورين؟","title":"حكم تغسيل الرجل من مات من محارمه","answer":"الجواب: ليس للرجل أن يغسل المرأة، سواء كانت أمه، أو أخته، أو بنته إلا الزوجة فقط، أو السرية التي يملكها، ويباح له جماعها وهي المملوكة، ومن عداهما من النساء ليس للرجل تغسيلها، ولكن يغسل النساء النساء، ويغسل الرجال الرجال، إلا الزوجة فقط، فقد غسل علي فاطمة -رضي الله عنها- وقد غسلت زوجة الصديق أسماء بنت عميس غسلت زوجها الصديق  وهكذا السرية سواء مثل الزوجة، السرية المملوكة التي يحل له جماعها؛ لأنها مملوكة له ملكًا شرعيًا، فإنها تغسله ويغسلها كالزوجة. أما كونه يغسل أمه، أو بنته، أو أخته فلا، ولكن إذا ما كان ما عندهم مرة؛ تُيمم؛ يمسح وجهها، ويديها بالتراب، ييممها ويكفي إذا كان ما عندهم نساء، ولا زوج لها فإنها تيمم، يعني: وليها يمسح وجهها بالتراب، ييمم وجهها وكفيها ثم يصلى عليها .... يعني: تيمم، وتكفن، ويصلى عليها. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11733/حكم-تغسيل-الرجل-من-مات-من-محارمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_527/52709.mp3","categories":["غسل الميت وتجهيزه"]},{"id":14862,"question":"المستمع: ميزار عبدالقوي زيدان، مقيم في العراق، يقول: كان لي ثلاثة أصدقاء غرقوا في البحر، وتوفوا إلى رحمة الله، قمت بغسلهم في المستشفى، لكني لا أعرف الطريقة الصحيحة للغسل الشرعي، هل علي إثم؟","title":"حكم من غسل ميتًا دون معرفة بالغسل الشرعي","answer":"الجواب: ما دمت عممتهم بالماء وغسلتهم بالماء غسلًا كاملًا، فإنه يجزئ والحمد لله.  أما الغسل الشرعي فإنه يبدأ أولًا بالاستنجاء إذا كان خرج منه شيء من بول أو غائط، يجعل الغاسل على يديه خرقة فيغسل دبره وفرجه عن الأذى، ويصب الماء، ويغطي ما بين السرة والركبة عن الأنظار، ثم بعد ذلك يوضئه الوضوء الشرعي، يمسح فمه وأنفه بالماء، ويغسل وجهه وذراعيه، ويمسح رأسه وأذنيه، ويغسل رجليه، ثم يفيض الماء على رأسه مع السدر، بالماء والسدر على رأسه، ثم على جنبه الأيمن ثم الأيسر، ثم يكمل غسله، هذا هو الأفضل، ويجعل في الغسلة الأخيرة كافورًا، وهو طيب معروف، يقوي الجسد، ويطيب الرائحة، هذا هو الأفضل. وكيفما غسل أجزأ، كيفما غسله أجزأه، المهم أن يعمه الماء ويزيل الأذى، لكن الأفضل أنه يبدأ بالاستنجاء، ثم الوضوء الشرعي، ثم يغسله بالماء والسدر ثلاث غسلات، يغسل رأسه أولًا بالماء والسدر ثلاث مرات، ثم يفيض الماء على جسده ثلاث مرات الأيمن، ثم الأيسر، ثلاث غسلات، فإن احتاج أزيد من ثلاث فخمس، فإن احتاج أكثر فسبع، يقطع على وتر هذا هو الأفضل، وإن غسله واحدة أو ثنتين أجزأه ذلك، لكن الأفضل ثلاثًا فخمسًا فسبعًا إذا احتيج إلى ذلك، والأفضل بكل حال ثلاث، ثلاث غسلات، لكن إذا احتاج إلى أزيد؛ لأن عليه أوساخ كثيرة، فيكون خمس على وتر، فإن لم تكف زاد إلى سابعة حتى يزيل الأوساخ، وينظف الميت، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13359/حكم-من-غسل-ميتا-دون-معرفة-بالغسل-الشرعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_645/nour_64502.mp3","categories":["غسل الميت وتجهيزه"]},{"id":15045,"question":"أحمد صالح النعيم من جدة، جامعة الملك عبدالعزيز ، يقول: سؤالي هو عن كيفية غسل النبي ﷺ، أو تكفينه والصلاة عليه ودفنه، وفقكم الله؟","title":"كيفية غسل النبي ﷺ وتكفينه والصلاة عليه","answer":"الجواب: الرسول ﷺ غسل في ثيابه، فإنهم سمعوا مناديًا، الصحابة لما اختلفوا هل يجردونه أم لا؟ سمعوا مناديًا من داخل البيت يقول: أن غسلوا رسول الله في ثيابه، فغسلوه بثيابه، وصبوا الماء عليه، وغسلوه في ثيابه -عليه الصلاة والسلام-، ثم كفنوه في ثلاثة أثواب بيض سحولية من كرسف، يعني: من قطن، ليس فيها قميص، ولا عمامة، كما جاء في حديث عائشة -رضي الله عنها-، ثم صلى عليه الناس -عليه الصلاة والسلام- فرادى، ما أمهم عليه إمام بل صلى عليه الناس، كل يدخل ويصلي عليه في المسجد -عليه الصلاة والسلام-، نعم.","link":"https://binbaz.org.sa/fatwas/13574/كيفية-غسل-النبي-ﷺ-وتكفينه-والصلاة-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_654/nour_65407.mp3","categories":["غسل الميت وتجهيزه","الصلاة على الميت"]},{"id":15384,"question":"هذه أول رسالة في حلقتنا اليوم من المستمع عبدالوهاب عبدالوهاب عبدالله عبدالجليل اليماني، من مكة المكرمة، يقول في سؤاله الأول:توفيت امرأة في القرية، وغسلها رجل أجنبي، وولدها موجود، وزوجة ولدها موجودة، ونساء كثيرات أيضًا، أما كان منه أن يعلم أحد النساء بدلًا من هذا الرجل الأجنبي لغسل هذه الميتة، فما الحكم في فعله هذا؟","title":"حكم تغسيل الرجل للمرأة الأجنبية المتوفاة","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه،أما بعد: هذا العمل منكر، وليس للرجل أن يغسل المرأة التي ليست زوجة له، ولا أمة له، والواجب أن يغسلها النساء، هذا هو الواجب، وهذا خطأ، وعليه التوبة إلى الله ، وعلى ابنها التوبة إلى الله، حيث تساهل في هذا الأمر، الواجب أن يغسل النساء النساء، إلا الزوجة يغسلها زوجها لا بأس، والأمة المملوكة التي تحل لسيدها، فإنه يغسلها أيضًا، وأما غيرهما فلا، الرجال لا يغسلون النساء، ولو كان محرمًا لها، ولو كان أبوها، ولو كان أخاها، ولو كان عمها، ليس له تغسيلها، يغسلها النساء، نعم.","link":"https://binbaz.org.sa/fatwas/13888/حكم-تغسيل-الرجل-للمراة-الاجنبية-المتوفاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_684/nour_68401.mp3","categories":["غسل الميت وتجهيزه"]},{"id":15584,"question":"هذا سؤال من المستمع (أ.ع) من الرياض، يقول: أرجو إيضاح كيفية صفة غسل الجنازة، وتكفين الميت، والفرق بين تكفين الذكر والأنثى؟","title":"صفة غسل الميت وتكفينه","answer":"الجواب: غسل الميت فرض، فرض كفاية؛ لأن الرسول ﷺ أمر بغسل الموتى، فيغسل كما يغتسل المؤمن الحي يغسل جميع جسده من رأسه إلى قدميه، يعم بالغسل مرة واحدة، هذا الواجب، والأفضل أن يبدأ بمواضع الوضوء؛ لأن الرسول ﷺ أمر بالبدء بمواضع الوضوء، فيمسح أسنانه وأنفه ويغسل وجهه ثلاثًا أفضل، وذراعيه مع المرفقين ثلاثًا، ويمسح رأسه مع أذنيه، ويغسل قدميه ذكرًا كان أو أنثى، ثم يصب الماء على رأسه ثلاث مرات، ويغسله بماء وسدر، ثم يفيض الماء على جسده بادئًا بالشق الأيمن قبل الأيسر، حتى يعم البدن مرة واحدة، هذا الواجب، وإذا كرره ثلاثًا يكون أفضل، إذا كرر غسله ثلاثًا أو خمسًا يكون أفضل وترًا، هذا هو الأفضل. \nوإذا كان به أوساخ أو لصوقات يزيد في الغسل حتى تزول الأوساخ كلها، ولو إلى سبع لكن وترًا وترًا أفضل حتى تزول الأوساخ واللصوقات، وينقى البدن بالماء والسدر.  ويستحب أن يكون فيه كافور في الغسلة الأخيرة شيء من الكافور؛ لأن هذا يطيب الجسد ويصلبه ويقويه، ويطيب الرائحة. ثم يكفن في ثوب يستره جميعًا من رأسه إلى قدميه، قطعة من الثوب تستره، والأفضل في ثلاث ثلاث لفائف كما كفن النبي ﷺ في ثلاث لفائف، تبسط واحدة فوق واحدة، ثم تلف عليه، ويحزم ما فوق رأسه، وما تحت رجليه بحزام، وهكذا وسطه، وتربط العقد عليه على رأسه ورجليه ووسطه حتى لا يخرج من الكفن، أطرافه فوق الرأس تربط وأطرافه بعد الرجلين تربط، وهكذا وسطه حتى يستقر، فإذا وضع في اللحد شرع حل هذه العقد تحل وتبقى على حالها، تفك وتبقى على حالها. وإن كفن في قميص...... يعني، ولفافة ومئزر، كفى ذلك، والمرأة تكون في قميص ومئزر وخمار على رأسها ولفافتين هذا الأفضل، خمس قطع: إزار، وقميص -مدرعة-، وخمار على رأسها، ثم تلف في لفافتين وتحزم.\nالمقدم: تدرج فيها. الشيخ: تدرج فيها، وتحزم ما فوق الرأس، وما تحت الرجلين والوسط، حتى ينضبط الكفن، هذا هو الأفضل، نعم. المقدم: إنما المجزئ في الغسل هو تعميم الماء على بدنه؟ الشيخ: تعميم الماء، والثوب واحد يكفي في الكفن للمرأة والرجل، إذا كفى وغطى البدن كله، كفى، لكن الزيادات هذه كلها مستحبة، نعم. المقدم: المشتركون في غسل الجنازة هل عليهم غسل بعد ذلك أو وضوء؛ إعادة الوضوء؟\nالشيخ: واحد هو الذي يتولى هذا الشيء، وآخر يصب عليه الماء، والعورة مستورة ما بين السرة والركبة تستر، ويصب الماء عليه حتى ينقى مثلما تقدم، وفي أول غسلة عندما ينجى بالخرقة يرفع قليلًا، يرفع رأسه وظهره حتى يتهيأ إن كان هناك شيء يخرج، يخرج، ثم ينظف بالخرقة فرجه، نعم، وينجى بالماء حتى يزول ما كان خرج من شيء، ثم يوضأ الوضوء الشرعي جميع أطرافه، كما تقدم مواضع الوضوء، يبدأ بمسح الفم والأنف وغسل الوجه، ثم اليدين، ثم مسح الرأس والأذنين، ثم غسل الرجلين، كما تقدم، ثم يعم بالماء هذا هو المشروع في حقه، وهو غسل واجب؛ لأن النبي ﷺ قال: اغسلوه بماء وسدر للذي مات في عرفات، وأمر النساء أن يغسلن ابنته بثلاث أو خمس أو سبع وترًا -عليه الصلاة والسلام-، وأمر أن يبدأ بميامنها، ومواضع الوضوء منها -عليه الصلاة والسلام-، فدل ذلك على أن هذا هو الأفضل، وهو الأكمل، ويكون في الماء سدر، بماء وسدر، وأمرهم أن يجعلوا في الأخيرة كافورًا، شيئًا من كافور، كما تقدم، نعم. المقدم: أقصد الذي يغسل الميت هل عليه غسل؟\nالشيخ: والذي يغسله يُستحب له الغسل، كان النبي ﷺ يغتسل من غسل الميت، إذا فرغ يغتسل بعد ذلك غسلًا، هذا هو الأفضل. وذهب بعض أهل العلم إلى أنه يجب عليه الوضوء أيضًا الوضوء...، تغسيل الميت ينقض الوضوء، قاله جمع من أهل العلم، وروي عن بعض الصحابة، فإذا توضأ الوضوء الشرعي واغتسل يكون أفضل. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14132/صفة-غسل-الميت-وتكفينه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_693/nour_69303.mp3","categories":["غسل الميت وتجهيزه"]},{"id":15933,"question":"هذا سائل سماحة الشيخ يقول: هل يجوز أن نلبس الميت قميص وسروال وعمامة ثم نقوم بلفه بثلاثة أثواب بيضاء؟ أفيدونا بذلك.","title":"كيفية كفن الميت","answer":"الجواب: الأفضل ثلاث لفائف، هذا هو الأفضل، وإن كفن في قميص وإزار ولفافة فلا بأس، وإن كفن في لفافة واحدة فلا بأس، ولكن الأفضل له ثلاثة لفائف، هذا هو الأفضل؛ كما فعل بالنبي ﷺ. المقدم: اللهم صل وسلم عليه.","link":"https://binbaz.org.sa/fatwas/14534/كيفية-كفن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_578/57803.mp3","categories":["غسل الميت وتجهيزه"]},{"id":16160,"question":"من أحد الإخوة المستمعين رسالة لم يذكر اسمه فيها يقول: هل الميت يلبس ملابس غير الكفن عند الدفن ذكرًا كان أم أنثى، أم يكتفى بالكفن؟الشيخ: أعد ..المقدم: السؤال مرة أخرى: هل الميت يلبس ملابس غير الكفن، سواء كان ذكرًا، أم أنثى؟ أم يكتفى بالكفن؟ جزاكم الله خيرًا.","title":"صفة كفن الميت","answer":"الجواب: السنة الاكتفاء بالكفن، الكفن يكفي، إذا كفن الرجل بثلاثة أثواب هي لفائف يلف فيها، هذا هو الأفضل، أو لفافة واحدة يلف فيها يكفي، وإن لبس قميصًا مع اللفافة؛ فلا حرج، لكن الأفضل ثلاث لفائف تبسط بسطًا، ثم تلف الأولى، ثم الثانية ثم الثالثة، ثم تربط عليه عند رأسه، وعند وسطه، وعند رجليه. والمرأة كذلك تلبس إزارًا، وقميصًا، وخمارًا، ثم لفافتين، ويكفيها هذا، ولا حاجة إلى الزيادة على هذا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14823/صفة-كفن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_804/nour_80413.mp3","categories":["غسل الميت وتجهيزه"]},{"id":16277,"question":"تقول: بعض الناس إذا مات لهم ميت يحفرون له في الأرض، ويكسرون البلاط الذي في الغرفة التي مات فيها، ويغسلونه فيها؛ لادعائهم أن الماء الذي يغسل به الميت لا يجوز رميه في الخارج، فما الحكم في هذا؟الشيخ: أعد.المقدم: تقول: بعض الناس إذا مات لهم ميت يحفرون له في الأرض، ويكسرون البلاط الذي في الغرفة التي مات فيها، ويغسلونه فيها؛ لادعائهم أن الماء الذي يغسل به الميت لا يجوز رميه في الخارج، فما الحكم في ذلك؟ جزاكم الله خيرًا.","title":"حكم رمي الماء الذي غسل به الميت","answer":"الجواب: هذا كلام باطل، عملًا لا أصل له، هذه من خرافات العامة، فماء الميت الذي يغسل به يراق مثل المياه الأخرى في الحمام وغيره، لا شيء فيه، يغسل في الحمام، أو في غير الحمام، ولا يحفر له، ولا تنقض البلاط، كل هذا غلط، كل هذا إضاعة المال بالباطل، نعم. المقدم: جزاكم الله خيرًا. الشيخ: نسأل الله العافية. المقدم: اللهم آمين.. اللهم آمين.","link":"https://binbaz.org.sa/fatwas/14969/حكم-رمي-الماء-الذي-غسل-به-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_752/nour_75208.mp3","categories":["غسل الميت وتجهيزه"]},{"id":16431,"question":"يقول: سمعت من بعض أئمة المساجد أنه إذا توفيت المرأة لا يجوز لزوجها أن يغسلها، وذلك لأنها أجنبية عنه بوفاتها، هل هذا صحيح؟!","title":"جواز تغسيل الرجل لزوجته إذا توفيت","answer":"الجواب: ليس بصحيح، الصواب أن له غسلها إذا ماتت، ولها هي أيضًا أن تغسله إذا مات؛ لأن السنة ثبتت بما يدل على ذلك، وغسلت أسماء بنت عميس زوجها الصديق  لما مات، وغسل علي زوجته فاطمة... غسل علي  زوجته فاطمة، رضي الله عنها.  فالمقصود: أن تغسيل الزوج لزوجته، والزوجة لزوجها أمر لا بأس به؛ لأنه أعلم بها، وهي أعلم بحاله، وقد بقيت علقة بينهما، وهي العدة، فلا بأس، ولا حرج في تغسيله لها وتغسيلها له، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15128/جواز-تغسيل-الرجل-لزوجته-اذا-توفيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_715/nour_71507.mp3","categories":["غسل الميت وتجهيزه"]},{"id":16843,"question":"من فاجأه الموت -سماحة الشيخ- لسبب، أو لآخر وهو جنب؛ هل يكون آثمًا؟","title":"حكم من فاجأه الموت وهو على جنابة","answer":"الجواب: لا، ما يكون آثمًا إذا كان ما فرط ما يكون آثمًا، مثلًا أخر غسل الجنابة، أتى أهله بعد طلوع الشمس، أو بعد الفجر، ثم فاجأه الأجل في الضحى؛ ما عليه شيء، لكن يغسل عن نية الجنابة، وعن نية الموت، يكفي غسل واحد، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15620/حكم-من-فاجاه-الموت-وهو-على-جنابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_824/nour_82415.mp3","categories":["غسل الميت وتجهيزه"]},{"id":17276,"question":"حفظكم الله هذا سائل يقول في هذا السؤال السائل من اليمن أحمد عبده: امرأة ماتت، وليس في القرية مغسلة تغسلها، وزوجها قد مات أيضًا من قبلها، و هل يجوز لأولادها أن يقوموا بتغسيلها؟","title":"هل يجوز تغسيل الأبناء لأمهم المتوفاة؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فإذا ماتت المرأة، ولم يوجد من يغسلها من النساء؛ فإنها تيمم، أولادها ييممونها بالتراب في وجهها، وكفيها، ويكفي بنية غسل الميت، وليس لهم النظر إلى عورتها، ولا تغسيلها، إن وجد امرأة تغسلها فالحمد لله، وإن لم يوجد أحد فإنها تيمم، ولكن في الغالب إن ما دامت في القرية إذا التمسوا وجدوا، لكن لو قدر أنهم لم يجدوا فإنها تيمم، ييممها أولادها بالتراب الطهور في الوجه والكفين بنية غسل الجنابة، غسل الموت، بنية غسل الميت، ويكفي. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16117/هل-يجوز-تغسيل-الابناء-لامهم-المتوفاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_593/59301.mp3","categories":["غسل الميت وتجهيزه"]},{"id":18595,"question":"هذا سائل يقول: ما حكم تغسيل السقط -يا سماحة الشيخ- عند موته؟","title":"حكم تغسيل السقط","answer":"الجواب: يجب تغسيل الميت إذا كمل أربعة أشهر، إذا ولد في الخامس أو السادس يغسل ويكفن ويصلى عليه، ويصلى عليه بين المسلمين، إذا كان ولد في الخامس بعدما نفخت فيه الروح يجب تغسيله وتكفينه والصلاة عليه بين المسلمين. نعم.","link":"https://binbaz.org.sa/fatwas/17700/حكم-تغسيل-السقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_918/nour_91813.mp3","categories":["غسل الميت وتجهيزه"]},{"id":18750,"question":"هذه السائلة مريم من المنطقة الشمالية تقول: بأنها امرأة متزوجة تبلغ من العمر الثامنة والثلاثين، تصلي وتصوم، وقامت بالتعلم في كيفية تغسيل النساء المتوفيات، ولقد قامت امرأة كبيرة وقالت لها: بأنه لا يجوز لها بأن تغسل الميت؛ كونها ما زالت امرأة تأتيها أو يأتيها العذر الشرعي، وحلفت يمين بأن لا تغسل أحدًا، ثم اضطرت لتغسيل ميتة؛ لأن أهلها لم يجدوا من يقوم بتغسيلها فقامت بذلك، هل هذا صحيح بأن المرأة لا تغسل النساء كونها يأتيها العذر الشهري؟","title":"حكم تغسيل الحائض للموتى من النساء","answer":"الجواب: هذا الكلام باطل، لها أن تغسل ولو أن تأتيها العادة، فالمقصود: أن المرأة تغسل النساء، أو تغسل زوجها، ولا بأس سواء كانت تأتيها العادة أو ما تأتيها العادة، والأمر في هذا واسع، والحمد لله، سواء شابة أو كبيرة تأتيها العادة أو ما تأتيها العادة. أما هذه التي حلفت فعليها كفارة يمين، أنها ما تغسل ثم غسلت عليها كفارة يمين عن يمينها، وهي إطعام عشرة مساكين، أو كسوتهم، لكل مسكين نصف صاع من قوت البلد كيلو ونصف من قوت البلد، من تمر أو غيره، أو كسوتهم كل واحد له قميص أو إزار ورداء عن يمينها. وأما هذه التي قالت لها: لا تغسلي وأنت تأتيك العادة هذا غلط، فالمرأة تغسل النساء، وتغسل زوجها مطلقًا سواء كانت شابة تأتيها العادة، أو عجوزًا، نعم.","link":"https://binbaz.org.sa/fatwas/17883/حكم-تغسيل-الحاىض-للموتى-من-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_790/nour_79009.mp3","categories":["غسل الميت وتجهيزه","الحيض والنفاس","قضايا المرأة"]},{"id":18761,"question":"سماحة الشيخ، ونحن نتحدث عن الحقيقة عن تغسيل وتكفين الموتى، هل من كلمة تجاه من يقومون محتسبين بتغسيل الأموات، ويبتغون الأجر من الله ؟","title":"كلمة إلى مغسلي الموتى من الرجال والنساء","answer":"الجواب: نعم. يستحب للمؤمن أن يساعد إخوانه المسلمين بتغسيل الميت والمرأة كذلك، هذا من باب التعاون على الخير، الرجل الذي يحسن الغسل، والمرأة التي تحسن الغسل؛ يشرع لهما جميعًا أن يساعدوا في هذا الأمر، الرجل يغسل الميت، ويغسل زوجته أيضًا، والمرأة كذلك تغسل الميت من النساء، وتغسل زوجها، وإذا تعلمت، وتعلم الرجل ذلك للإحسان؛ فهذا خير عظيم، وفضل كبير؛ لأن الناس يحتاجون إلى هذا، يحتاجون إلى من يغسل موتاهم من الرجال والنساء. فيشرع للرجل أن يفعل ذلك ويحتسب، ويشرع للمرأة أن تفعل وتحتسب لمسيس الحاجة إلى هذا الأمر، والأمر واضح بحمد الله مبين موضح في كتب أهل العلم، كيف تغسيل الميت، يراجع كتب أهل العلم، ويستفيد في كتاب الجنائز في تغسيل الميت، فصل في تغسيل الميت، وقد وضح العلماء فيه الكيفية، فالمرأة تراجع، والرجل يراجع، ويستفيد، ويسأل أهل العلم عما أشكل عليه، نعم. المقدم: جزاكم الله خيرًا، سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17885/كلمة-الى-مغسلي-الموتى-من-الرجال-والنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_790/nour_79011.mp3","categories":["غسل الميت وتجهيزه"]},{"id":19299,"question":"أخونا يسأل ويقول: ما رأيكم في امرأة عمرها حوالي السبعين تغسل الصبية والأولاد الصغار إذا توفوا؟","title":"حكم تغسيل المرأة للصبيان المتوفين","answer":"الجواب: نعم، لا بأس إذا كانوا دون السبع فلا بأس أن تغسلهم المرأة إذا كان الصبي دون السبع؛ فإنه تغسله المرأة ويغسله الرجل، وهكذا البنت الصغيرة دون السبع يغسلها الرجل والمرأة جميعًا، فإذا بلغ الذكر سبعًا غسله الرجال، وإذا بلغت الجارية سبعًا غسلها النساء، وما دون السبع أمره واسع من الرجال والنساء. نعم. المقدم: جزاكم الله خيرًا","link":"https://binbaz.org.sa/fatwas/18516/حكم-تغسيل-المراة-للصبيان-المتوفين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_894/nour_89413.mp3","categories":["غسل الميت وتجهيزه"]},{"id":19420,"question":"يسأل أخونا عن الطريقة الصحيحة لغسل الميت، كيف توجهون الناس جزاكم الله خيرًا؟","title":"صفة غسل الميت","answer":"الجواب: الطريقة الصحيحة لغسل الميت المشروعة: أن الغاسل يبدأ فينجي الميت بخرقة .... خرقة وينجيه إذا كان خرج منه شيء، يرفعه بعض الشيء حتى يخرج ما .... يرفعه كالقاعد من غير جلوس كامل حتى يخرج إن كان هناك شيء من بول أو غائط .... فإن خرج شيء غسله ونظفه بالماء بخرقة في يده، ثم بعد ذلك يوضئه وضوء الصلاة. أما إن كان ما خرج منه شيء فليس هناك حاجة إلى الاستنجاء، بل يوضئه الوضوء الشرعي، يمسح فمه ومنخريه بالماء ويغسل وجهه وذراعيه مع المرفقين ويمسح رأسه بالماء وأذنيه ويغسل رجليه، ثم بعد ذلك يغسل شعر رأسه بالماء والسدر، ثم بدنه الشق الأيمن ثم الأيسر ثلاث مرات، فإن احتاج إلى زيادة غسله خمس مرات أو سبع مرات كما أمر النبي بهذا عليه الصلاة والسلام لما غسلوا ابنته زينب قال: اغسلنها بثلاث أو خمس أو أكثر من ذلك إن رأيتن ذلك بماء وسدر -هذا السنة- واجعلن في الأخيرة كافورًا هذا السنة يكون في الغسلة الأخيرة شيئًا من الكافور؛ لأنه يطيب الرائحة ويصلب الجسم، والسدر مع الماء ينظف، فهذا هو المسنون في غسل الميت. أولًا: ينجيه إن كان خرج منه شيء، ثم يوضئه وضوء الصلاة، ثم يغسل رأسه بالماء والسدر، ثم يفيض الماء على جسده بالماء والسدر، يبدأ بالشق الأيمن ثم الأيسر، ثم يعممه بالماء ثلاث مرات، وإن احتاج إلى أكثر كأن يكون فيه وسخ زاد إلى خمس أو إلى سبع حتى يزيل ما هناك من وسخ، ويكون الماء فاترًا ليس بحار كثير وليس ببارد، بل يكون من الماء الفاتر الذي يعين على إزالة الأوساخ من دون أن يكون حارًا حرًا شديدًا، يكون حارًا حرًا خفيفًا إذا دعت الحاجة إليه، وإن غسل بماء ليس بحار فلا بأس إذا كان ما هناك حاجة إليه، أما إذا كان هناك حاجة كأن يكون فيه أوساخ تحتاج إلى ماء حار يكون هناك ماء حار لا يؤذي لكن مع السدر هذا السنة، نعم. المقدم: جزاكم الله خيراً. أخونا يقول. الشيخ: ولو غسل غسلة واحدة كفى، لو غسل غسلة واحدة ولم يكرر لأنه نظيف كفى ذلك، ولهذا يقول ﷺ في قصة الذي مات في عرفات لما سقط عن دابته قال: اغسلوه بماء وسدر ولم يأمر بالتكرار، قال: اغسلوه بماء وسدر وكفنوه في ثوبيه ولم يقل ثلاثًا ولا غيرها، فدل على أنه يجزي الغسلة الواحدة، لكن إذا دعت الحاجة إلى الثلاث أو كررها للاحتياط فحسن؛ لأن الرسول ﷺ قال في زينب: اغسلنها ثلاثًا تكرار الثلاث حسن، وإن دعت الحاجة إلى أكثر فكذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18650/صفة-غسل-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_937/nour_93702.mp3","categories":["غسل الميت وتجهيزه"]}]
